using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace LWS.TruckSubmarine.Tests {
 public sealed class SubmarineLifecycleTests {
  const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static readonly string CaptureId=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff");
  static Type Sports(string n)=>Type.GetType("LWS.TruckSports."+n+", Assembly-CSharp",true);static object Get(object x,string n)=>x.GetType().GetField(n,Any) is FieldInfo f?f.GetValue(x):x.GetType().GetProperty(n,Any).GetValue(x);static void Set(object x,string n,object v)=>x.GetType().GetField(n,Any).SetValue(x,v);static object Call(object x,string n,params object[] a)=>x.GetType().GetMethods(Any).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||(p.ParameterType.IsByRef?p.ParameterType.GetElementType():p.ParameterType).IsInstanceOfType(a[i])).All(ok=>ok)).Invoke(x,a);static Rigidbody Body(object x)=>(Rigidbody)Get(x,"body");static object Registry(string n,params object[]a)=>Sports("SportsParticipantRegistry").GetMethod(n).Invoke(null,a);
