   readonly IDisposable prefs;readonly GameObject isolation;readonly InputSettings prior,focus;readonly Gamepad previousPad;readonly List<Gamepad> pads=new List<Gamepad>();
   public Behaviour match;public object rules;public object[] divers,cargo;public object[] trucks;public Vector3 gravity;public float[] masses;Rigidbody[] originalBodies;float[] originalMasses;float nextTrace;readonly System.Text.StringBuilder trace=new System.Text.StringBuilder(24000);string tracePath;
   public Fixture(){prefs=(IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"SubmarineNative"+Guid.NewGuid().ToString("N")});Registry("ForgetCache");prior=InputSystem.settings;previousPad=Gamepad.current;focus=UnityEngine.Object.Instantiate(prior);focus.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;focus.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;focus.updateMode=InputSettings.UpdateMode.ProcessEventsInDynamicUpdate;InputSystem.settings=focus;isolation=new GameObject("Submarine native input isolation");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Sports("SportsProbeInputIsolation"));gravity=Physics.gravity;}
   public Gamepad Pad(){var p=InputSystem.AddDevice<Gamepad>();pads.Add(p);InputSystem.EnableDevice(p);p.MakeCurrent();Assert.That(p.added&&p.enabled&&Gamepad.current==p,Is.True);return p;}
   public IEnumerator Load(){Assert.That(File.Exists("Assets/TruckSubmarine/Scenes/TruckSubmarine.unity"),Is.True,"Lead must explicitly author the NEW detailed expedition scene before native validation.");EditorSceneManager.LoadSceneInPlayMode("Assets/TruckSubmarine/Scenes/TruckSubmarine.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=UnityEngine.Object.FindObjectsByType(Type.GetType("LWS.TruckSubmarine.SubmarineMatch, Assembly-CSharp",true),FindObjectsSortMode.None).Cast<Behaviour>().Single();rules=Get(match,"rules");divers=((Array)Get(match,"divers")).Cast<object>().ToArray();cargo=((Array)Get(match,"treasures")).Cast<object>().ToArray();trucks=divers.Select(d=>Get(d,"truck")).ToArray();masses=trucks.Select(Body).Select(b=>b.mass).ToArray();var ballastBodies=divers.Select(d=>(Rigidbody)Get(d,"ballast")).ToArray();originalBodies=divers.SelectMany(d=>((Component)d).GetComponentsInChildren<Rigidbody>(true)).Where(b=>!ballastBodies.Contains(b)).ToArray();originalMasses=originalBodies.Select(b=>b.mass).ToArray();Assert.That(divers.Length,Is.EqualTo(4));Assert.That(cargo.Length,Is.EqualTo(25));Assert.That(trucks.All(t=>Get(t,"tractorMotor")!=null&&Get(t,"appearanceHost")!=null),Is.True);string dir="Logs/TruckSports/PlaytestRepair/SubmarineControlledNative/"+CaptureId;Directory.CreateDirectory(dir);tracePath=Path.Combine(dir,"physical-"+Guid.NewGuid().ToString("N")+".txt");}
   public void Start(int count=4,int option=0){Call(match,"SetupScreen");Set(Get(match,"setup"),"count",count);Set(match,"option",option);Call(match,"NormalizeSetup");Call(match,"AllBots");var players=(Array)Get(Get(match,"setup"),"players");for(int i=0;i<count;i++){var player=players.GetValue(i);var f=player.GetType().GetField("difficulty");f.SetValue(player,Enum.ToObject(f.FieldType,2));}Assert.That((bool)Call(match,"StartMatch"),Is.True);nextTrace=0;}
   public void Observe(){float clock=(float)Get(rules,"Clock");if(clock<nextTrace)return;nextTrace=clock+4;string s="SUBMARINE_PHYSICAL clock="+clock+" phase="+Get(rules,"Phase")+" delivered="+Get(match,"NativeDeliveries")+" AIplans="+Get(match,"AIPlans");for(int i=0;i<(int)Get(Get(match,"setup"),"count");i++){var d=divers[i];var rb=Body(trucks[i]);var b=Get(d,"buoyancy");s+=" | slot"+i+" p="+rb.position.ToString("F3")+" v="+rb.linearVelocity.ToString("F3")+" mass="+rb.mass+" ballast="+Get(d,"Ballast")+" wet="+Get(b,"WetTriangles")+" hydroSteps="+Get(b,"Steps")+" sonar="+Get(d,"SonarPulses")+" contacts="+Get(d,"NativeGripperContacts")+" cargo="+(Get(d,"Carrying") is object held?Get(held,"id"):"none")+" integrity="+((float[])Get(rules,"integrity"))[i];}trace.AppendLine(s);File.WriteAllText(tracePath,trace.ToString());TestContext.WriteLine(s);}
   public void Dispose(){Time.timeScale=1;try{if(match!=null){match.enabled=true;Call(match,"SetupScreen");Assert.That(Physics.gravity,Is.EqualTo(gravity));if(trucks!=null&&masses!=null)for(int i=0;i<trucks.Length;i++)Assert.That(Body(trucks[i]).mass,Is.EqualTo(masses[i]),"Original NWH root mass remains exact.");if(originalBodies!=null)for(int i=0;i<originalBodies.Length;i++)Assert.That(originalBodies[i].mass,Is.EqualTo(originalMasses[i]),"Every original NWH/Cab rigidbody mass remains exact; only the separate owned ballast varies.");}}finally{foreach(var p in pads)if(p.added)InputSystem.RemoveDevice(p);UnityEngine.Object.DestroyImmediate(isolation);Registry("ForgetCache");prefs.Dispose();InputSystem.settings=prior;UnityEngine.Object.DestroyImmediate(focus);if(previousPad!=null&&previousPad.added&&previousPad.enabled)previousPad.MakeCurrent();}}
  }
  static IEnumerator Until(Func<bool> ready,float seconds,string message){float end=Time.realtimeSinceStartup+seconds;while(!ready()&&Time.realtimeSinceStartup<end)yield return null;Assert.That(ready(),Is.True,message);}
  static IEnumerator Capture(Behaviour match,string name,int width,int height){yield return null;yield return null;string dir="Logs/TruckSports/PlaytestRepair/SubmarineControlledNative/"+CaptureId;Directory.CreateDirectory(dir);string path=Path.Combine(dir,"controlled-"+name+".png");var save=Sports("SportsControlledCapture").GetMethods().Single(m=>m.Name=="Save"&&m.GetParameters().Length==5&&m.GetParameters()[0].ParameterType.IsInstanceOfType(match));save.Invoke(null,new object[]{match,width,height,path,null});var image=new Texture2D(2,2);try{Assert.That(File.Exists(path)&&image.LoadImage(File.ReadAllBytes(path)),Is.True);Assert.That(new Vector2Int(image.width,image.height),Is.EqualTo(new Vector2Int(width,height)));}finally{UnityEngine.Object.DestroyImmediate(image);}TestContext.WriteLine("SUBMARINE_CONTROLLED_NATIVE "+path+"; Camera.Render+UI composite, not actual GameView/Windows/human acceptance.");}
  [UnityTest,Timeout(180000)]public IEnumerator FourRealAiUseVendorBuoyancyScanContactCarryDeliverFinishAndRematch(){using(var f=new Fixture()){yield return f.Load();f.Start();string id=(string)Get(f.match,"MatchId");Time.timeScale=3;bool carried=false,paused=false,captured=false;float end=Time.realtimeSinceStartup+140;while(!(bool)Get(f.match,"Finished")&&Time.realtimeSinceStartup<end){f.Observe();carried|=f.divers.Any(d=>Get(d,"Carrying")!=null);if(!captured&&(int)Get(f.match,"NativeDeliveries")>0){captured=true;Time.timeScale=1;yield return Capture(f.match,"natural-AI-delivery-720",1280,720);yield return Capture(f.match,"natural-AI-delivery-1080",1920,1080);Time.timeScale=3;}if(!paused&&carried){paused=true;Call(f.match,"Pause",0,false);float clock=(float)Get(f.rules,"Clock");int[] points=((int[])Get(f.rules,"points")).ToArray();var poses=f.trucks.Select(Body).Select(b=>b.position).ToArray();yield return new WaitForSecondsRealtime(.2f);Assert.That((float)Get(f.rules,"Clock"),Is.EqualTo(clock));Assert.That((int[])Get(f.rules,"points"),Is.EqualTo(points));for(int i=0;i<poses.Length;i++)Assert.That(Vector3.Distance(poses[i],Body(f.trucks[i]).position),Is.LessThan(.001f));Call(f.match,"Resume");Time.timeScale=3;}yield return null;}
   Assert.That((bool)Get(f.match,"Finished"),Is.True,"Finite actual expedition must finish without synthetic completion.");Assert.That(carried&&paused&&captured,Is.True,"Native gripper pickup, carry pause and actual delivery must all occur.");Assert.That((int)Get(f.match,"NativeDeliveries"),Is.GreaterThan(0));Assert.That(((int[])Get(f.rules,"points")).Sum(),Is.GreaterThan(0));Assert.That(f.divers.Sum(d=>(int)Get(d,"SonarPulses")),Is.GreaterThan(0));Assert.That(f.divers.Sum(d=>(int)Get(d,"NativeGripperContacts")),Is.GreaterThan(0));Assert.That(f.divers.All(d=>(int)Get(Get(d,"buoyancy"),"Steps")>0),Is.True);Assert.That((int)Get(Get(f.match,"ScoreJournal"),"Count"),Is.GreaterThan(0));f.Start();Assert.That((string)Get(f.match,"MatchId"),Is.Not.EqualTo(id));Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);Assert.That(f.cargo.All(c=>!(bool)Get(c,"Banked")&&(int)Get(c,"Owner")==-1),Is.True);}}
  [UnityTest,Timeout(70000)]public IEnumerator RealHydrostaticAndPropellerForcesPreserveNwhAndPressureFailureStaysInPlace(){using(var f=new Fixture()){yield return f.Load();f.Start(1);yield return Until(()=>Get(f.rules,"Phase").ToString()=="Diving",8,"Actual countdown releases submarine.");var diver=f.divers[0];var truck=f.trucks[0];var rb=Body(truck);f.match.enabled=false;Call(truck,"TickDrive",Vector2.zero);rb.linearVelocity=Vector3.down*.4f;float before=rb.linearVelocity.y;int steps=(int)Get(Get(diver,"buoyancy"),"Steps");for(int i=0;i<8;i++)yield return new WaitForFixedUpdate();Assert.That((int)Get(Get(diver,"buoyancy"),"Steps"),Is.GreaterThan(steps));Assert.That(Convert.ToUInt32(Get(Get(diver,"buoyancy"),"WetTriangles")),Is.GreaterThan(0));Assert.That(rb.linearVelocity.y,Is.GreaterThan(before+Physics.gravity.y*Time.fixedDeltaTime*8*.7f),"Real vendor hydrostatics must oppose free-fall; no second buoyancy force is allowed.");var start=rb.position;for(int i=0;i<70;i++){Call(diver,"Pilot",new Vector2(0,1),1f,0f,0f,Time.fixedDeltaTime);yield return new WaitForFixedUpdate();}Assert.That(rb.position.z-start.z,Is.GreaterThan(.5f));Assert.That(rb.position.y-start.y,Is.GreaterThan(.2f),"Physical vertical propeller force must ascend.");Assert.That(Body(truck).mass,Is.EqualTo(f.masses[0]));
   f.match.enabled=true;Call(f.match,"SetupScreen");Set(Get(f.match,"setup"),"count",1);Call(f.match,"NormalizeSetup");var player=((Array)Get(Get(f.match,"setup"),"players")).GetValue(0);var keyboard=InputSystem.AddDevice<Keyboard>();try{InputSystem.EnableDevice(keyboard);keyboard.MakeCurrent();Set(player,"source",Enum.Parse(player.GetType().GetField("source").FieldType,"Keyboard"));Assert.That((bool)Call(f.match,"StartMatch"),Is.True);yield return Until(()=>Get(f.rules,"Phase").ToString()=="Diving",8,"Pressure fixture begins only after actual countdown.");rb.position=new Vector3(0,-130,80);rb.rotation=Quaternion.identity;rb.linearVelocity=Vector3.zero;Physics.SyncTransforms();Time.timeScale=3;yield return Until(()=>{f.Observe();return ((bool[])Get(f.rules,"retired"))[0];},15,"Actual over-depth physical pose must exhaust pressure integrity.");Assert.That(rb.isKinematic,Is.True);Assert.That(Vector3.Distance(rb.position,new Vector3(0,-130,80)),Is.LessThan(40),"Pressure retires at actual depth, never teleports to spawn or buoy.");Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);}finally{if(keyboard.added)InputSystem.RemoveDevice(keyboard);}}}
  [UnityTest,Timeout(60000)]public IEnumerator OneThroughFourViewsKeepOriginalOwnersAndWaterState(){using(var f=new Fixture()){yield return f.Load();Sports("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});var views=Get(f.match,"drivingViews");Call(views,"Select",1);for(int n=1;n<=4;n++){f.Start(n);yield return null;yield return null;var rally=Get(views,"rally");Assert.That(((int[])Get(rally,"owners")).Take(n),Is.EqualTo(Enumerable.Range(0,n)));var cameras=(Camera[])Get(f.match,"cameras");Assert.That(cameras.Length,Is.EqualTo(n));Assert.That(cameras.Sum(c=>c.rect.width*c.rect.height),Is.EqualTo(1).Within(.001f));for(int i=0;i<n;i++){object[]args={i,-1,null,null};Assert.That((bool)f.match.GetType().GetMethod("TryReadViewportCard").Invoke(f.match,args),Is.True);Assert.That((int)args[1],Is.EqualTo(i));Assert.That((string)args[2],Is.EqualTo("0 PTS"));Assert.That(cameras[i].GetComponent(Type.GetType("LWS.TruckBogSnorkelling.BogCameraEffects, Assembly-CSharp",true)),Is.Not.Null);}yield return Until(()=>Get(f.rules,"Phase").ToString()=="Diving",8,"Each viewport's sonar uses the actual live expedition.");for(int i=0;i<n;i++)Call(f.divers[i],"Sonar");yield return null;yield return null;var guidance=f.match.GetComponent(Type.GetType("LWS.TruckSubmarine.SubmarineSonarGuidance, Assembly-CSharp",true));var compasses=(Array)Get(guidance,"compasses");var markers=(Array)Get(guidance,"markers");for(int i=0;i<n;i++){var compass=compasses.GetValue(i);Assert.That((int)Get(compass,"compassGroup"),Is.EqualTo(i+1),"Vendor CNP group IDs are1–4 only.");Assert.That((int)Get(markers.GetValue(i),"compassGroupMask"),Is.EqualTo(1<<i));Assert.That((Transform)Get(compass,"follow"),Is.EqualTo(((Component)f.trucks[i]).transform));Assert.That((Camera)Get(compass,"cameraMain"),Is.EqualTo(cameras[i]));Assert.That(((Array)Get(compass,"permittedTargets")).Length,Is.EqualTo(1));Assert.That(((Array)Get(compass,"permittedTargets")).GetValue(0),Is.EqualTo(markers.GetValue(i)),"Existing CNP sees only this viewport's discovered/held target.");}}yield return Capture(f.match,"four-owner-underwater-720",1280,720);Call(views,"Select",0);yield return null;yield return null;Assert.That(((Camera[])Get(f.match,"cameras")).Length,Is.EqualTo(1));var sharedGuidance=f.match.GetComponent(Type.GetType("LWS.TruckSubmarine.SubmarineSonarGuidance, Assembly-CSharp",true));var sharedCompass=((Array)Get(sharedGuidance,"compasses")).GetValue(4);var sharedMarker=((Array)Get(sharedGuidance,"markers")).GetValue(4);Assert.That((int)Get(sharedCompass,"compassGroup"),Is.EqualTo(1));Assert.That((int)Get(sharedMarker,"compassGroupMask"),Is.EqualTo(1));Assert.That(((Array)Get(sharedCompass,"permittedTargets")).GetValue(0),Is.EqualTo(sharedMarker),"Mutually exclusive shared view retains its explicit single-target allowlist.");}}
  [UnityTest,Timeout(65000)]public IEnumerator AuthoredWildlifeAndConfiguredRareSquidAnimateAtActualDeepTruckAndPause(){using(var f=new Fixture()){yield return f.Load();var presentation=Get(f.match,"presentation");var squid=Get(presentation,"squid");Set(squid,"encounterChance",1f);f.Start(1,2);Time.timeScale=3;var wildlife=(Animator[])Get(presentation,"wildlife");Assert.That(wildlife.Length,Is.EqualTo(18));Assert.That(wildlife.All(a=>a.runtimeAnimatorController!=null),Is.True);yield return Until(()=>(float)Get(f.rules,"Clock")>=36,20,"Actual expedition clock reaches encounter window.");var rb=Body(f.trucks[0]);rb.position=new Vector3(0,-105,80);rb.linearVelocity=Vector3.zero;Physics.SyncTransforms();yield return Until(()=>(bool)Get(squid,"Encountered"),3,"Configured chance1 diagnostic still requires a real deep truck near encounter volume.");var joints=(Transform[])Get(squid,"armJoints");var before=joints.Select(j=>j.localRotation).ToArray();int frames=(int)Get(squid,"AnimatedFrames");yield return new WaitForSeconds(.5f);Assert.That((int)Get(squid,"AnimatedFrames"),Is.GreaterThan(frames));Assert.That(joints.Where((j,i)=>Quaternion.Angle(j.localRotation,before[i])>.1f).Count(),Is.GreaterThan(0));Assert.That(wildlife.All(a=>a.GetCurrentAnimatorStateInfo(0).normalizedTime>.1f),Is.True,"Installed marine animation controllers advance on actual authored rigs.");Time.timeScale=1;yield return Capture(f.match,"configured-rare-squid-deep-truck-720",1280,720);Call(f.match,"Pause",0,false);frames=(int)Get(squid,"AnimatedFrames");yield return new WaitForSecondsRealtime(.2f);Assert.That((int)Get(squid,"AnimatedFrames"),Is.EqualTo(frames));Call(f.match,"Resume");TestContext.WriteLine("SUBMARINE_SQUID configured encounterChance1 controlled diagnostic; natural default rare encounter remains separately unobserved.");}}
  [UnityTest,Timeout(70000)]public IEnumerator FourSoftwarePadsOwnPropulsionAltitudeBallastAndHalfPadInputs(){using(var f=new Fixture()){yield return f.Load();Call(f.match,"SetupScreen");Set(Get(f.match,"setup"),"count",4);Call(f.match,"NormalizeSetup");var players=(Array)Get(Get(f.match,"setup"),"players");var pads=new Gamepad[4];for(int i=0;i<4;i++){pads[i]=f.Pad();var p=players.GetValue(i);Set(p,"source",Enum.Parse(p.GetType().GetField("source").FieldType,"WholeController"));Set(p,"pad",pads[i]);InputSystem.QueueStateEvent(pads[i],new GamepadState());}Assert.That((bool)Call(f.match,"StartMatch"),Is.True);yield return Until(()=>Get(f.rules,"Phase").ToString()=="Diving",8,"Actual countdown.");yield return null;var starts=f.trucks.Select(Body).Select(b=>b.position).ToArray();for(int i=0;i<4;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState{rightTrigger=.8f}.WithButton(GamepadButton.RightShoulder).WithButton(GamepadButton.DpadUp).WithButton(GamepadButton.West));float end=Time.realtimeSinceStartup+2;while(Time.realtimeSinceStartup<end)yield return null;for(int i=0;i<4;i++){Assert.That(((Vector2[])Get(f.match,"commands"))[i].y,Is.GreaterThan(.7f));Assert.That(Vector3.Distance(starts[i],Body(f.trucks[i]).position),Is.GreaterThan(.3f));Assert.That((float)Get(f.divers[i],"Ballast"),Is.GreaterThan(.05f));Assert.That((int)Get(f.divers[i],"SonarPulses"),Is.GreaterThan(0));Assert.That((string)Get(Get(f.trucks[i],"appearanceHost"),"ProfileId"),Is.EqualTo((string)Get(players.GetValue(i),"participantId")));}
   Call(f.match,"SetupScreen");Set(Get(f.match,"setup"),"count",2);Call(f.match,"NormalizeSetup");for(int i=0;i<2;i++){var p=players.GetValue(i);Set(p,"source",Enum.Parse(p.GetType().GetField("source").FieldType,i==0?"LeftStick":"RightStick"));Set(p,"pad",pads[0]);}InputSystem.QueueStateEvent(pads[0],new GamepadState());Assert.That((bool)Call(f.match,"StartMatch"),Is.True);yield return Until(()=>Get(f.rules,"Phase").ToString()=="Diving",8,"Two halves retain original shared-controller ownership.");yield return null;InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.LeftShoulder));yield return null;yield return null;object[]left={0,0f,0f,0f,false},right={1,0f,0f,0f,false};Call(f.match,"ReadControls",left);Call(f.match,"ReadControls",right);Assert.That((float)left[1],Is.EqualTo(1));Assert.That((float)right[1],Is.Zero,"Left shoulder cannot actuate right-half altitude.");}}
